import * as React from "react";
import { cn } from "cn";
import { Dialog as SheetPrimitive } from "radix-ui";

import { useV4PortalContainer } from "../scope";
import { Button } from "./button";
import { Icon } from "./icon";

import { useOwnedEscape } from "../lib/use-owned-escape";

import overlay from "./overlay.module.css";

function Sheet({ ...props }: React.ComponentProps<typeof SheetPrimitive.Root>) {
  return <SheetPrimitive.Root data-slot="sheet" {...props} />;
}

const SheetTrigger = React.forwardRef<
  React.ElementRef<typeof SheetPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Trigger>
>(({ ...props }, ref) => {
  return <SheetPrimitive.Trigger ref={ref} data-slot="sheet-trigger" {...props} />;
});
SheetTrigger.displayName = "SheetTrigger";

const SheetClose = React.forwardRef<
  React.ElementRef<typeof SheetPrimitive.Close>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Close>
>(({ ...props }, ref) => {
  return <SheetPrimitive.Close ref={ref} data-slot="sheet-close" {...props} />;
});
SheetClose.displayName = "SheetClose";

function SheetPortal({ ...props }: React.ComponentProps<typeof SheetPrimitive.Portal>) {
  return (
    <SheetPrimitive.Portal container={useV4PortalContainer()} data-slot="sheet-portal" {...props} />
  );
}

const SheetOverlay = React.forwardRef<
  React.ElementRef<typeof SheetPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Overlay>
>(({ className, ...props }, ref) => {
  return (
    <SheetPrimitive.Overlay
      ref={ref}
      data-slot="sheet-overlay"
      className={cn("z-50", overlay.scrim, overlay.scrimSlow, className)}
      {...props}
    />
  );
});
SheetOverlay.displayName = "SheetOverlay";

const SheetContent = React.forwardRef<
  React.ComponentRef<typeof SheetPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Content> & {
    side?: "top" | "right" | "bottom" | "left";
    showCloseButton?: boolean;
  }
>(
  (
    { className, children, side = "right", showCloseButton = true, onEscapeKeyDown, ...props },
    ref
  ) => {
    const escape = useOwnedEscape(ref, onEscapeKeyDown);
    return (
      <SheetPortal>
        <SheetOverlay />
        <SheetPrimitive.Content
          ref={escape.ref}
          data-slot="sheet-content"
          data-side={side}
          className={cn(
            "fixed z-50 flex flex-col gap-4 data-[side=bottom]:inset-x-0 data-[side=bottom]:bottom-0 data-[side=bottom]:h-auto data-[side=left]:inset-y-0 data-[side=left]:left-0 data-[side=left]:h-full data-[side=left]:w-3/4 data-[side=right]:inset-y-0 data-[side=right]:right-0 data-[side=right]:h-full data-[side=right]:w-3/4 data-[side=top]:inset-x-0 data-[side=top]:top-0 data-[side=top]:h-auto data-[side=left]:sm:max-w-sm data-[side=right]:sm:max-w-sm",
            overlay.pop,
            overlay.sheet,
            className
          )}
          {...props}
          onEscapeKeyDown={escape.onEscapeKeyDown}
        >
          {children}
          {showCloseButton && (
            <SheetPrimitive.Close data-slot="sheet-close" asChild>
              <Button variant="ghost" className={overlay.close} size="icon-sm">
                <Icon name="x" />
                <span className="sr-only">Close</span>
              </Button>
            </SheetPrimitive.Close>
          )}
        </SheetPrimitive.Content>
      </SheetPortal>
    );
  }
);
SheetContent.displayName = "SheetContent";

const SheetHeader = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="sheet-header"
      className={cn("flex flex-col gap-0.5 p-4", className)}
      {...props}
    />
  );
});
SheetHeader.displayName = "SheetHeader";

const SheetBody = React.forwardRef<HTMLDivElement, React.ComponentPropsWithoutRef<"div">>(
  ({ className, ...props }, ref) => (
    <div ref={ref} data-slot="sheet-body" className={cn(className)} {...props} />
  )
);
SheetBody.displayName = "SheetBody";

const SheetFooter = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="sheet-footer"
      className={cn("mt-auto flex flex-col gap-2 p-4", className)}
      {...props}
    />
  );
});
SheetFooter.displayName = "SheetFooter";

const SheetTitle = React.forwardRef<
  React.ComponentRef<typeof SheetPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Title>
>(({ className, ...props }, ref) => {
  return (
    <SheetPrimitive.Title
      ref={ref}
      data-slot="sheet-title"
      className={cn("text-foreground", className)}
      {...props}
    />
  );
});
SheetTitle.displayName = "SheetTitle";

const SheetDescription = React.forwardRef<
  React.ComponentRef<typeof SheetPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Description>
>(({ className, ...props }, ref) => {
  return (
    <SheetPrimitive.Description
      ref={ref}
      data-slot="sheet-description"
      className={cn("text-muted-foreground", className)}
      {...props}
    />
  );
});
SheetDescription.displayName = "SheetDescription";

export {
  Sheet,
  SheetBody,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
  SheetTrigger
};

.scrim {
  position: fixed;
  inset: 0;
  background-color: var(--v4-scrim);
}
.scrim[data-state="open"] {
  animation: fadeIn var(--v4-duration-slow) var(--v4-ease-fade) both;
}
.scrim[data-state="closed"] {
  animation: fadeOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.pop {
  box-sizing: border-box;
  background-color: var(--v4-pop);
  color: var(--v4-ink);
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-pop-line),
    var(--v4-shadow-pop);
  outline: none;
}
.dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  display: grid;
  width: calc(100% - 2 * var(--v4-space-16));
  max-width: var(--v4-size-dialog);
  max-height: calc(100dvh - 2 * var(--v4-space-16));
  overflow-y: auto;
  translate: -50% -50%;
}
.dialog[data-state="open"] {
  animation: dialogIn var(--v4-duration-slow) var(--v4-ease-spring-soft) both;
}
.dialog[data-state="closed"] {
  animation: dialogOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.palette {
  top: 33%;
  max-width: var(--v4-size-dialog-wide);
  overflow: hidden;
  translate: -50% 0;
}
.close[data-slot] {
  position: absolute;
  top: calc(
    var(--v4-space-overlay-inset) + (var(--v4-type-title-line-height) - var(--v4-size-nested-md)) /
      2
  );
  inset-inline-end: calc(
    var(--v4-space-overlay-inset) - (var(--v4-size-nested-md) - var(--v4-size-icon)) / 2
  );
}
.sheet {
  --v4-sheet-from: 100% 0;
}
.sheet[data-side="left"] {
  --v4-sheet-from: -100% 0;
}
.sheet[data-side="top"] {
  --v4-sheet-from: 0 -100%;
}
.sheet[data-side="bottom"] {
  --v4-sheet-from: 0 100%;
}
.sheet[data-state="open"] {
  animation: sheetIn var(--v4-duration-slow) var(--v4-ease-spring-soft) both;
}
.sheet[data-state="closed"] {
  animation: sheetOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.drawer.drawer[data-vaul-drawer] {
  transition-duration: var(--v4-duration-slow);
  transition-timing-function: var(--v4-ease-spring-soft);
  animation-duration: var(--v4-duration-slow);
  animation-timing-function: var(--v4-ease-spring-soft);
  animation-fill-mode: both;
}
.drawer.drawer[data-vaul-drawer][data-state="closed"] {
  transition-duration: var(--v4-duration-exit-slow);
  transition-timing-function: var(--v4-ease-exit);
  animation-duration: var(--v4-duration-exit-slow);
  animation-timing-function: var(--v4-ease-exit);
}
.handle {
  display: none;
  flex: none;
  width: var(--v4-space-48);
  height: var(--v4-space-4);
  margin: var(--v4-space-12) auto 0;
  border-radius: calc(var(--v4-radius-pop) * var(--corners));
  background-color: var(--v4-control);
}
[data-vaul-drawer-direction="bottom"] > .handle {
  display: block;
}
.scrim.scrim[data-vaul-overlay] {
  animation-duration: var(--v4-duration-slow);
  animation-timing-function: var(--v4-ease-fade);
  animation-fill-mode: both;
}
.scrim.scrim[data-vaul-overlay][data-state="closed"] {
  animation-duration: var(--v4-duration-exit-slow);
  animation-timing-function: var(--v4-ease-exit);
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
}
@keyframes fadeOut {
  to {
    opacity: 0;
  }
}
@keyframes dialogIn {
  from {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes dialogOut {
  to {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes sheetIn {
  from {
    translate: var(--v4-sheet-from);
  }
}
@keyframes sheetOut {
  to {
    translate: var(--v4-sheet-from);
  }
}
@media (prefers-reduced-motion: reduce) {
  .dialog[data-state="open"],
  .sheet[data-state="open"] {
    animation-name: fadeIn;
  }
  .dialog[data-state="closed"],
  .sheet[data-state="closed"] {
    animation-name: fadeOut;
  }
  .drawer.drawer[data-vaul-drawer] {
    transition: none;
  }
  .drawer.drawer.drawer[data-vaul-drawer][data-state="open"] {
    animation-name: fadeIn;
  }
  .drawer.drawer.drawer[data-vaul-drawer][data-state="closed"] {
    animation-name: fadeOut;
  }
}
